import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); print(json.dumps(G))

d=G['Demo pair 1 output']
def f(x):
    g=[r[:] for r in x]; H=len(g); W=len(g[0])
    col=[cc for cc in range(W) if len(set(g[r][cc] for r in range(H)))==1 and next(iter(set(g[r][cc] for r in range(H))))!=7][0]
    c=g[0][col]
    marks=[(r,cc,g[r][cc]) for r in range(H) for cc in range(W) if g[r][cc]!=7 and cc!=col]
    out=[r[:] for r in g]
    rs=[r for r,_,_ in marks]; cs=[cc for _,cc,_ in marks]
    r1,r2=min(rs),max(rs)
    # fill block: rows r1..r2, cols from min(cs) to line? but marker cells themselves... check row5: cols3,4 = 4,2 -> so col4 became 2 (marker). col3=4.
    # maybe block is cols cmin..line-1 filled with c, then markers overwrite their row segment cmin..line with mv
    for r in range(r1,r2+1):
        for cc in range(min(cs)+1,col):
            out[r][cc]=c
    for r,mc,mv in marks:
        for cc in range(mc,col):
            out[r][cc]=mv
    return out
