def solve(g):
    g=[r[:] for r in g]; h=len(g); w=len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    dom=cnt.most_common(2)[0][0]
    sep_rows=[k for k in range(h) if len(set(g[k]))==1 and g[k][0]!=dom]
    out=[r[:] for r in g]
    marks=[(i,j,g[i][j]) for i in range(h) for j in range(w)
           if g[i][j]!=dom and g[i][j] not in {g[r][0] for r in sep_rows}]
    crosses=[]
    for mi,mj,k in marks:
        ups=[s for s in sep_rows if s<mi]; dns=[s for s in sep_rows if s>mi]
        for s in ([max(ups)] if ups else [])+([min(dns)] if dns else []):
            for t in range(min(mi,s)+1,max(mi,s)):
                out[t][mj]=k
            out[s][mj]=k
            crosses.append((s,mj,g[s][0]))
    for s,mj,sc in crosses:
        for di in (-1,0,1):
            for dj in (-1,0,1):
                if abs(di)+abs(dj)!=0 and 0<=s+di<h and 0<=mj+dj<w:
                    out[s+di][mj+dj]=sc
    return out
